const express = require('express');
const session = require('express-session');
const { Scalekit } = require('@scalekit-sdk/node');
const crypto = require('crypto');

const app = express();
const port = 3001;

// Initialize Scalekit client with placeholder values
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://your-env.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

app.use(session({
  secret: 'a-very-secret-key',
  resave: false,
  saveUninitialized: true,
  cookie: { secure: false } // Set to true if using HTTPS
}));

app.get('/login', (req, res) => {
  const organization_id = req.query.organization_id;
  if (!organization_id) {
    return res.status(400).send('organization_id query parameter is required');
  }

  // Generate a random state string
  const state = crypto.randomBytes(16).toString('hex');

  // Store state in session
  req.session.state = state;

  // Generate authorization URL
  const options = {
    redirectUri: 'http://localhost:3001/callback',
    state: state,
    organizationId: organization_id
  };

  const authUrl = scalekit.getAuthorizationUrl(options);

  // Redirect the user
  res.redirect(authUrl);
});

app.get('/callback', (req, res) => {
  // Callback implementation not strictly required by the prompt but good for testing
  res.send('Callback received');
});

app.listen(port, () => {
  console.log(`Scalekit app listening at http://localhost:${port}`);
});

